cat > $TMPDIR/Try.java <<'EOF'
import org.apache.commons.lang3.builder.*;

public class Try {
    static class Job {
        String title;
        Job(String title) { this.title = title; }
    }
    static class Person {
        String name;
        int age;
        boolean smoker;
        Job job;
        int[] scores;
    }
    public static void main(String[] args) {
        Person p = new Person();
        p.name = "Stephen";
        p.age = 29;
        p.smoker = false;
        p.job = new Job("Manager");
        p.scores = new int[]{1,2,3};
        String s = new ReflectionToStringBuilder(p, new MultilineRecursiveToStringStyle()).toString();
        System.out.println("===");
        System.out.println(s);
        System.out.println("===");
        for (char c : s.toCharArray()) {
            if (c=='\n') System.out.print("\\n\n"); else System.out.print(c);
        }
    }
}
EOF
javac -cp target/classes -d $TMPDIR $TMPDIR/Try.java && java -cp target/classes:$TMPDIR Try
